import json,sys
d=json.load(open('windows.json'))
def walk(o,out):
    if isinstance(o,dict):
        t=o.get('type')
        if t=='text' and 'text' in o: out.append(o['text'])
        if t=='codeVoice' and 'code' in o: out.append(o['code'])
        if t=='heading' and 'text' in o: out.append('\n## '+o['text'])
        for k,v in o.items():
            if k in ('text','code'): continue
            walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
